/* From Uiverse.io by Creatlydev - Tags: switch, creative, toggle switch */
.__UIV_SCOPE__ .container {
  margin: auto;
  color: hsl(0, 0%, 30%);
  font-weight: 900;
  font-size: 6rem;
  display: flex;
}

.__UIV_SCOPE__ .toggle {
  width: 60px;
  height: 155px;
  background-color: hsl(0, 0%, 80%);
  border-radius: 1.7rem;
  padding: .25rem 0;
  cursor: pointer;
  display: flex;
  justify-content: center;
  transition: background-color 300ms 300ms;
}

.__UIV_SCOPE__ .toggle__circle {
  width: 50px;
  height: 50px;
  background-color: hsl(0, 0%, 95%);
  border-radius: 50%;
  margin-top: calc(155px - (.25rem * 2) - 50px);
  transition: margin 500ms ease-in-out;
}

.__UIV_SCOPE__ .toggle-text {
  display: flex;
  flex-direction: column;
  line-height: .8;
}

.__UIV_SCOPE__ #check:checked + .toggle > .toggle__circle {
  margin-top: 0;
}

.__UIV_SCOPE__ #check:checked + .toggle {
  background-color: #41a63c;
}
